mapper.select:
SELECT ps.id FROM ip_pool_status ps WHERE ps.audit_status = '20' AND ps.is_deleted = 0
AND ps.target_pool_id IN
#{poolId}
AND (EXISTS ( SELECT 1 FROM ip_adjust_log src WHERE src.adjust_batch_no = ps.adjust_batch_no AND src.adjust_type = 'Excel导入' AND src.adjust_mode = '调入' AND src.audit_status = '20' AND src.is_deleted = 0 )
OR ps.adjust_reason LIKE '【任务名称：%】【主体跟随】（%【Excel主体跟随】%'
)

SELECT al.id , al.security_code , al.target_pool_id , al.adjust_mode , al.audit_time , al.crte_time FROM ip_adjust_log al WHERE al.security_type = 'company' AND al.security_code IS NOT NULL AND al.audit_status = '20' AND al.is_deleted = 0
AND al.target_pool_id IN
#{poolId}
AND al.security_code IN
#{code}
AND (al.adjust_type = 'Excel导入' OR EXISTS ( SELECT 1 FROM ip_adjust_log src WHERE src.adjust_batch_no = al.adjust_batch_no AND src.security_type = 'company' AND src.adjust_type = 'Excel导入' AND src.audit_status = '20' AND src.is_deleted = 0 ))
